function CodigoEncontroRoute({
  selectedUserId,
  userPapel,
  apiClient,
}: {
  selectedUserId: string | null;
  userPapel?: string;
  apiClient: typeof api;
}) {
  const { encontroId } = useParams<{ encontroId: string }>();
  return (
